<?php
namespace App\Http\Controllers; use App\Models\{Contract,FreeReport,FreeReportTemplate}; use App\Services\WordDocumentExporter;
class WordExportController extends Controller { public function contract(Contract $contract,WordDocumentExporter $word){return $word->download('CONTRACT '.$contract->number,['Titlu'=>$contract->title,'Client'=>$contract->client?->name,'Conținut'=>$contract->content,'Observații'=>$contract->observations], 'contract-'.$contract->number.'.docx');} public function report(FreeReport $report,WordDocumentExporter $word){return $word->download($report->title,['Număr'=>$report->number,'Data'=>$report->document_date?->format('d.m.Y'),'Client'=>$report->client_name,'Locație'=>$report->location,'Participanți'=>$report->participants,'Subiect'=>$report->subject,'Conținut'=>$report->content,'Constatări'=>$report->findings,'Concluzii'=>$report->conclusions,'Observații'=>$report->observations], 'proces-verbal-'.$report->number.'.docx');} public function template(FreeReportTemplate $freeReportTemplate,WordDocumentExporter $word){return $word->download($freeReportTemplate->data['title']??'Șablon proces-verbal',$freeReportTemplate->data,'sablon-proces-verbal-'.$freeReportTemplate->id.'.docx');} }
